export interface GameEvent {
  id: string;
  type: EventType;
  priority: EventPriority;
  location: { x: number; y: number };
  timer: number;
  points: number;
  cozinessReward: number;
  cozinessPenalty: number;
}

export class EventManager {
  spawnEvent(level: number, activeEventsCount?: number): GameEvent | null {
    // Uses EVENT_TYPE_TO_PRIORITY mapping
    // Creates events with properties from constants
  }
}

const EVENT_TYPE_TO_PRIORITY: Readonly<Record<EventType, EventPriority>> = {
  phone: 'standard',
  kettle: 'critical',
  cat: 'minor',
  candle: 'standard',
} as const;

export const EVENT_SCORING: Readonly<Record<EventPriority, number>> = {
  minor: 10,
  standard: 15,
  critical: 20,
} as const;

export const EVENT_COZINESS_IMPACT: Readonly<
  Record<EventPriority, { reward: number; penalty: number }>
> = {
  minor: { reward: 5, penalty: -5 },
  standard: { reward: 8, penalty: -10 },
  critical: { reward: 10, penalty: -20 },
} as const;

export function getEventTimerDuration(level: number): number {
  if (level <= 0) {
    return EVENT_TIMER_DURATION[1];
  }
  if (level <= 5) {
    return EVENT_TIMER_DURATION[level as keyof typeof EVENT_TIMER_DURATION];
  }
  return EVENT_TIMER_DURATION[5];
}
